from __future__ import annotations

import math
from typing import Callable, List, Tuple

Field = Tuple[str, str, str]
Calc = Callable[[List[float]], tuple[float, str]]


def _safe_div(a: float, b: float, label: str = "분모") -> float:
    if b == 0:
        raise ValueError(f"{label}는 0일 수 없습니다.")
    return a / b


def _sqrt(x: float) -> float:
    if x < 0:
        raise ValueError("제곱근 안의 값은 0 이상이어야 합니다.")
    return math.sqrt(x)


def _asin_deg(x: float) -> float:
    if not -1 <= x <= 1:
        raise ValueError("arcsin 입력은 -1~1 범위여야 합니다.")
    return math.degrees(math.asin(x))


